import { useState } from 'react';
import type { FormEvent } from 'react';
import { JxStepper, JxButton, JxInputField, JxTextareaField } from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  zip: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const EMPTY_DATA: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  address: '',
  city: '',
  zip: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY_DATA);
  const [errors, setErrors] = useState<Partial<Record<keyof RegistrationData, string>>>({});

  const setField = (field: keyof RegistrationData) => (e: FormEvent<HTMLInputElement>) => {
    setData((prev) => ({ ...prev, [field]: e.currentTarget.value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  };

  const validateStep = (): boolean => {
    const nextErrors: Partial<Record<keyof RegistrationData, string>> = {};
    if (step === 0) {
      if (!data.name.trim()) nextErrors.name = 'Укажите имя';
      if (!data.email.trim()) nextErrors.email = 'Укажите email';
      if (!data.phone.trim()) nextErrors.phone = 'Укажите телефон';
    }
    if (step === 1) {
      if (!data.address.trim()) nextErrors.address = 'Укажите адрес';
      if (!data.city.trim()) nextErrors.city = 'Укажите город';
      if (!data.zip.trim()) nextErrors.zip = 'Укажите индекс';
    }
    setErrors(nextErrors);
    return Object.keys(nextErrors).length === 0;
  };

  const handleNext = () => {
    if (!validateStep()) return;
    setStep((prev) => Math.min(prev + 1, STEPS.length - 1));
  };

  const handleBack = () => {
    setStep((prev) => Math.max(prev - 1, 0));
  };

  const handleSubmit = () => {
    if (!validateStep()) return;
    onSubmit(data);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r)',
        maxWidth: 480,
        padding: 'var(--jx-r-lg)',
        borderRadius: 'var(--jx-r-lg)',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={setField('name')}
            errorText={errors.name}
            placeholder="Иван Иванов"
          />
          <JxInputField
            label="Email"
            type="email"
            required
            value={data.email}
            onChange={setField('email')}
            errorText={errors.email}
            placeholder="name@example.com"
          />
          <JxInputField
            label="Телефон"
            type="tel"
            required
            prefix="+7"
            value={data.phone}
            onChange={setField('phone')}
            errorText={errors.phone}
            placeholder="900 000-00-00"
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
          <JxTextareaField
            label="Адрес"
            required
            value={data.address}
            onChange={setField('address') as any}
            errorText={errors.address}
            placeholder="Улица, дом, квартира"
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={setField('city')}
            errorText={errors.city}
            placeholder="Москва"
          />
          <JxInputField
            label="Индекс"
            required
            value={data.zip}
            onChange={setField('zip')}
            errorText={errors.zip}
            placeholder="123456"
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
          <p style={{ color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}>
            Проверьте данные перед отправкой:
          </p>
          <div style={{ color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)', lineHeight: 1.6 }}>
            <div>Имя: {data.name}</div>
            <div>Email: {data.email}</div>
            <div>Телефон: +7 {data.phone}</div>
            <div>Адрес: {data.address}</div>
            <div>Город: {data.city}</div>
            <div>Индекс: {data.zip}</div>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-r)' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={handleBack}>
          Назад
        </JxButton>
        {step < STEPS.length - 1 ? (
          <JxButton variant="primary" onClick={handleNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" type="submit" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

